              "shopping-cart": "cart-shopping", "trash": "trash", "plus": "plus", "minus": "minus",
              "check": "check", "x": "xmark", "settings": "gear", "home": "house", "user": "user",
              "users": "users", "calendar": "calendar", "clock": "clock", "search": "magnifying-glass",
